import { Icon, ICON_MOTION, ICON_NAMES } from './Icon'
import { Blob, Sticker, STICKER_NAMES } from './Decor'
import { useT } from '@/i18n'

/**
 * Every icon at every size, on both surfaces.
 *
 * Reachable at `#/ikon`. It exists so inconsistency is visible rather than
 * discovered one screen at a time — a new icon that is heavier, off-grid, or
 * illegible at 16 px shows up immediately next to its neighbours. The
 * screenshot suite captures this page, so a regression lands in a diff.
 */
export default function IconGallery() {
  const t = useT()
  return (
    <div className="stack">
      <h1>{t('ikon.title')}</h1>
      <p className="card__hint">{t('ikon.hint', { n: ICON_NAMES.length })}</p>

      <section className="card stack stack--tight">
        <h2 className="card__title">{t('ikon.onSurface')}</h2>
        <div className="icon-grid">
          {ICON_NAMES.map((name) => (
            <button key={name} type="button" className="icon-tile">
              <Icon name={name} size={24} animate />
              <span>{name}</span>
            </button>
          ))}
        </div>
      </section>

      {/* The motion table, readable. A wrong pairing (a lock that spins, a coin
          that latches) is obvious here and nowhere else. */}
      <section className="card stack stack--tight">
        <h2 className="card__title">{t('ikon.motion')}</h2>
        <p className="card__hint">{t('ikon.motionHint')}</p>
        <div className="motion-table">
          {ICON_NAMES.map((name) => (
            <button key={name} type="button" className="motion-row">
              <Icon name={name} size={22} animate />
              <span className="motion-row__name">{name}</span>
              <span className="chip chip--teal">{ICON_MOTION[name].replace('ic--', '')}</span>
            </button>
          ))}
        </div>
      </section>

      <section className="card stack stack--tight" style={{ position: 'relative', overflow: 'hidden' }}>
        <Blob seed={1} tone="teal" style={{ width: 180, top: -60, right: -50 }} />
        <h2 className="card__title">{t('ikon.stickers')}</h2>
        <p className="card__hint">{t('ikon.stickersHint')}</p>
        <div className="sticker-grid">
          {STICKER_NAMES.map((name) => (
            <div key={name} className="sticker-tile">
              <Sticker name={name} size={92} />
              <span>{name}</span>
            </div>
          ))}
        </div>
      </section>

      <section className="card stack stack--tight" style={{ background: 'var(--ink)' }}>
        <h2 className="card__title" style={{ color: 'var(--surface)' }}>
          {t('ikon.onDark')}
        </h2>
        <div className="icon-grid" style={{ color: 'var(--surface)' }}>
          {ICON_NAMES.map((name) => (
            <button key={name} type="button" className="icon-tile icon-tile--dark">
              <Icon name={name} size={24} animate />
              <span>{name}</span>
            </button>
          ))}
        </div>
      </section>

      <section className="card stack stack--tight">
        <h2 className="card__title">{t('ikon.sizes')}</h2>
        {[14, 16, 18, 20, 24, 28, 32].map((size) => (
          <div key={size} className="row" style={{ gap: 'var(--space-3)' }}>
            <span className="chip">{size}px</span>
            {(['home', 'heart', 'calendar', 'tasks', 'money', 'cycle', 'shield', 'repair'] as const).map(
              (n) => (
                <Icon key={n} name={n} size={size} />
              ),
            )}
          </div>
        ))}
      </section>

      <section className="card stack stack--tight">
        <h2 className="card__title">{t('ikon.states')}</h2>
        <div className="row" style={{ gap: 'var(--space-2)' }}>
          <button className="btn btn--sm">
            <Icon name="plus" size={16} /> {t('ikon.stateDefault')}
          </button>
          <button className="btn btn--soft btn--sm">
            <Icon name="check" size={16} /> {t('ikon.stateSoft')}
          </button>
          <button className="btn btn--ghost btn--sm">
            <Icon name="export" size={16} /> {t('ikon.stateGhost')}
          </button>
          <button className="btn btn--danger btn--sm">
            <Icon name="unpair" size={16} /> {t('ikon.stateDanger')}
          </button>
          <button className="btn btn--sm" disabled>
            <Icon name="settings" size={16} /> {t('ikon.stateDisabled')}
          </button>
          <button className="btn btn--ghost btn--sm btn--icon">
            <Icon name="close" size={16} label={t('ikon.iconOnly')} />
          </button>
        </div>
      </section>
    </div>
  )
}
